// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount1 = bound(amount1, 1, type(uint256).max / 2);
        amount2 = bound(amount2, 0, type(uint256).max - amount1);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.addToBalance{value: amount1}();
        vm.prank(actor);
        c.addToBalance{value: amount2}();

        assertTrue(c.getBalance(actor) == amount1 + amount2);
    }
}
